CREATE TABLE IF NOT EXISTS admin (id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL UNIQUE, password_hash BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY, token TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, billing_anchor INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS brands (name TEXT PRIMARY KEY COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS groups (name TEXT PRIMARY KEY COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS latency_tasks (id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS node_tasks (node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, task_id TEXT NOT NULL REFERENCES latency_tasks(id) ON DELETE CASCADE, position INTEGER NOT NULL, PRIMARY KEY(node_id, task_id));
CREATE INDEX IF NOT EXISTS node_tasks_order ON node_tasks(node_id, position);
CREATE TABLE IF NOT EXISTS channels (id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runtimes (node_id TEXT PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seen_boots (node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, boot_id TEXT NOT NULL, PRIMARY KEY(node_id, boot_id));
CREATE TABLE IF NOT EXISTS reports (node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, time INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reports_node_time ON reports(node_id,time);
CREATE INDEX IF NOT EXISTS reports_retention ON reports(time);
CREATE TABLE IF NOT EXISTS latency_results (node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, task_id TEXT NOT NULL REFERENCES latency_tasks(id) ON DELETE CASCADE, run_id TEXT NOT NULL, time INTEGER NOT NULL, status TEXT NOT NULL, value REAL, PRIMARY KEY(node_id,task_id,run_id));
CREATE INDEX IF NOT EXISTS latency_node_task_time ON latency_results(node_id,task_id,time);
CREATE INDEX IF NOT EXISTS latency_retention ON latency_results(time);
CREATE TABLE IF NOT EXISTS traffic_periods (node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, period TEXT NOT NULL, upload INTEGER NOT NULL DEFAULT 0, download INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(node_id,period));
